  'help.send': 'Tuma Tiketi',
  'help.ticketSent': 'Tiketi Imetumwa!',
  'help.ticketSentDesc': 'Tumezipokea ombi lako. Timu yetu itajibu kupitia barua pepe ndani ya masaa 24.',
  'help.close': 'Funga',
  'help.ticketError': 'Imeshindikana kutuma tiketi. Jaribu tena.',
  'help.type.cant_login': 'Siwezi kuingia',
  'help.type.email_issue': 'Tatizo na barua pepe',
  'help.type.security': 'Usalama',
  'help.type.other': 'Nyingine',
  'help.faq.cantLogin.q': 'Siwezi kufikia akaunti yangu',
  'help.faq.cantLogin.a': 'Hakiki kama unatumia barua pepe na nenosiri sahihi. Ikiwa umesahau nenosiri, bonyeza "Umesahau nenosiri?" kwenye skrini ya kuingia. Ikiwa tatizo linaendelea, tengeneza tiketi ya msaada.',
  'help.faq.notReceiving.q': 'Sipati barua pepe',
  'help.faq.notReceiving.a': 'Angalia folda ya Spam kwanza. Hakikisha hifadhi yako haijajaa. Ikiwa tatizo linaendelea, thibitisha kwamba mtumaji ana anwani sahihi na tengeneza tiketi.',
  'help.faq.cantSend.q': 'Siwezi kutuma barua pepe',
  'help.faq.cantSend.a': 'Angalia muunganisho wako wa intaneti na kama anwani ya mpokeaji ni sahihi. Hakiki kama viambatisho havizidi 25MB. Jaribu tena baada ya dakika chache.',
  'help.faq.forgotPassword.q': 'Nimesahau nenosiri langu',
  'help.faq.forgotPassword.a': 'Katika skrini ya kuingia, bonyeza "Umesahau nenosiri?" na fuata maelekezo ili kubadilisha nenosiri lako kupitia barua pepe ya urejelezi.',
  'help.faq.accountSecurity.q': 'Nafikiri akaunti yangu imeathiriwa',
  'help.faq.accountSecurity.a': 'Badilisha nenosiri lako mara moja. Angalia folda ya Iliyotumwa kwa ujumbe ambao hujatumwa. Weka uthibitisho wa hatua mbili kwenye Mipangilio > Usalama. Ikiwa ni lazima, tengeneza tiketi ya dharura.',
  'help.faq.appAccess.q': 'Ninawezaje kufikia app kwenye simu?',
  'help.faq.appAccess.a': 'Unaweza kufikia Chatyy kupitia kivinjari kwenye chatyy.com.br, au pakua app yetu kwenye duka la programu la kifaa chako.',
  'privacy.title': 'Sera ya Faragha',
  'privacy.subtitle': 'Jinsi tunavyolinda na kushughulikia data zako',
  'privacy.lastUpdated': 'Sasisho la mwisho: Machi 2026',
  'privacy.dataCollection.title': 'Kukusanya Data',
  'privacy.dataCollection.body': 'Tunakusanya tu taarifa muhimu kwa huduma ya barua pepe: jina lako, anwani ya barua pepe na maudhui ya ujumbe uliopelekwa na kupokelewa. Hatuuzi wala kushiriki data zako binafsi na watu wengine kwa madhumuni ya masoko.',
  'privacy.dataUsage.title': 'Jinsi Tunavyotumia Data Zako',
  'privacy.dataUsage.body': 'Data zako zinatumika pekee kwa ajili ya kuendesha na kuboresha huduma ya barua pepe, ikiwa ni pamoja na utoaji wa ujumbe, kuchuja spam, vipengele vya AI (kwa idhini yako) na usalama wa akaunti.',
  'privacy.dataSecurity.title': 'Usalama wa Data',
  'privacy.dataSecurity.body': 'Tunatumia usimbaji wa viwango vya tasnia (TLS/SSL) kwa data zote zinazosafirishwa na zilizohifadhiwa. Sesheni zinahifadhiwa kwa alama za usimbaji na ulinzi wa CSRF. Tunakagua mara kwa mara mbinu zetu za usalama.',
  'privacy.cookies.title': 'Cookies na Hifadhi ya Mitaa',
  'privacy.cookies.body': 'Tunatumia cookies muhimu na hifadhi ya ndani ili kudumisha sesheni yako, kukumbuka mapendeleo yako (mandhari, lugha) na kutoa uzoefu mzuri. Hatutumii cookies za ufuatiliaji kutoka kwa watu wengine.',
  'privacy.thirdParties.title': 'Huduma za Watu Wengine',
  'privacy.thirdParties.body': 'Tunaweza kutumia huduma za watu wengine kwa ajili ya vipengele maalum kama AI (Anthropic Claude) na arifa za push. Huduma hizi zinafuata sera zao za faragha na kushughulikia tu data chache zinazohitajika.',
  'privacy.rights.title': 'Haki Zako',
  'privacy.rights.body': 'Una haki ya kufikia, kurekebisha, kusafirisha au kufuta data zako binafsi wakati wowote. Unaweza kusimamia data zako kwenye Mipangilio au kuwasiliana na msaada wetu.',
  'privacy.contact.title': 'Wasiliana Nasi',
  'privacy.contact.body': 'Kwa masuala ya faragha au maombi ya data, wasiliana kupitia privacy@chatyy.com.br. Tutajibu ndani ya siku 30.',
  'terms.title': 'Masharti ya Huduma',
  'terms.subtitle': 'Miongozo ya matumizi ya Chatyy',
  'terms.lastUpdated': 'Sasisho la mwisho: Machi 2026',
  'terms.acceptance.title': 'Kukubali Masharti',
  'terms.acceptance.body': 'Kwa kufikia au kutumia Chatyy, unakubali Masharti haya ya Huduma. Ikiwa hukubaliani na sehemu yoyote ya masharti haya, usitumie huduma.',
  'terms.services.title': 'Maelezo ya Huduma',
  'terms.services.body': 'Chatyy inatoa huduma za mawasiliano kupitia barua pepe ikiwa ni pamoja na kutuma, kupokea na kusimamia barua pepe, pamoja na vipengele vya AI, ushirikiano na kalenda na videokonferensi.',
  'terms.accounts.title': 'Akaunti za Mtumiaji',
  'terms.accounts.body': 'Wewe ni responsible kwa kudumisha usalama wa taarifa zako. Usishiriki nenosiri lako wala kuruhusu ufikiaji usioidhinishwa kwenye akaunti yako. Lazima uwe na angalau miaka 13 ili kutumia huduma hii.',
  'terms.conduct.title': 'Matumizi Yanayokubalika',
  'terms.conduct.body': 'Unakubali kutotumia huduma kutuma spam, malware, phishing au maudhui yoyote haramu. Usijaribu kufikia akaunti za watumiaji wengine au kuingilia miundombinu ya huduma.',
  'terms.content.title': 'Umiliki wa Maudhui',
  'terms.content.body': 'Unashikilia umiliki wa maudhui yote unayounda na kutuma kupitia huduma. Hatudai umiliki wa barua pepe zako au viambatisho. Tunaweza kushughulikia maudhui kama inavyohitajika ili kutoa huduma.',
  'terms.limitation.title': 'Kikomo cha Wajibu',
  'terms.limitation.body': 'Chatyy inatolewa "kama ilivyo". Tunatafuta asilimia 99.9 ya upatikanaji lakini hatuhakikishi huduma isiyokatizwa. Hatuna wajibu kwa madhara yasiyo ya moja kwa moja, ya bahati mbaya au yanayotokana na matumizi ya huduma.',
  'terms.termination.title': 'Kufunga Akaunti',
  'terms.termination.body': 'Tunaweza kusitisha au kufunga akaunti zinazovunja masharti haya. Unaweza kufuta akaunti yako wakati wowote kwenye Mipangilio. Baada ya kufungwa, data zako zitatolewa ndani ya siku 30.',
  'terms.changes.title': 'Mabadiliko ya Masharti',
  'terms.changes.body': 'Tunaweza kusasisha masharti haya mara kwa mara. Tutakujulisha kuhusu mabadiliko makubwa kupitia barua pepe au arifa kwenye app. Kutumia huduma baada ya mabadiliko ni kukubali masharti yaliyosasishwa.',
