  'plans.storageWarningUpgrade': 'Fanya upgrade kwa Chatyy One na upate 200 GB!',
  'plans.faqWhatIsPlus': 'Chatyy One ni nini?',
  'plans.faqWhatIsPlusAnswer': 'Ni mpango wa premium wa Chatyy unaolinda mazungumzo yako yote, picha na video. Pamoja na Chatyy One, hata ukifuta kitu bila kukusudia, unaweza kukirejesha ndani ya siku 30. Zaidi ya hayo, unapata 200GB ya uhifadhi, One AI kama msaidizi wako wa kibinafsi, na unaweza kutuma faili za hadi 100MB.',
  'plans.faqCancelAnswer': 'Mpango wako utaendelea kuwa hai hadi mwisho wa kipindi kilicholipwa. Baada ya hapo, utarudi kwenye mpango wa bure. Picha na video zako zinazozidi 15GB zitawekwa kwa siku 30 zaidi ili uweze kupakua.',
  'plans.faqHowFamily': 'Mpango wa Pro unafanya kazi vipi?',
  'plans.faqHowFamilyAnswer': 'Unaweza kuongeza hadi watu 4 wa familia yako. Wote wanashiriki 500GB ya uhifadhi na wanapata faida zote za Chatyy One. Kila mtu ana nafasi yake binafsi — hakuna anayeona faili za wengine.',
  'plans.faqChangePlanAnswer': 'Ndio! Ikiwa unafanya upgrade kutoka Plus hadi Pro, utatozwa tu tofauti ya uwiano. Ikiwa unafanya downgrade, mpango wa sasa utaendelea hadi mwisho wa kipindi.',
  'plans.faqCardDeclined': 'Kadi yangu imekataliwa, nifanye nini?',
  'plans.faqCardDeclinedAnswer': 'Una siku 7 za kusasisha kadi yako. Wakati huu, faida zako zote zinaendelea kufanya kazi. Baada ya siku 7, mpango unarudi kwenye bure.',
  'plans.faqDataSafe': 'Je, data zangu ziko salama?',
  'plans.faqDataSafeAnswer': 'Ndio! Data zako za malipo zinashughulikiwa kwa usimbaji wa mwisho hadi mwisho. Hatuhifadhi nambari ya kadi yako — tunahifadhi tu tarakimu 4 za mwisho kwa kumbukumbu yako.',
